function(container, apiUrl, tables) {
  let currentOrder = null;
  let currentAnalysis = null;

  // 受注検索
  container.querySelector("#btn-search-order").addEventListener("click", async () => {
    const orderNumber = container.querySelector("#order-number-input").value.trim();
    if (!orderNumber) {
      alert("受注番号を入力してください");
      return;
    }

    // 受注データを検索
    const orders = await window.aivicApi.list(2); // 受注テーブル
    if (!orders) return;

    const order = orders.find(o => o.受注番号 === orderNumber);
    if (!order) {
      alert("該当する受注が見つかりません");
      return;
    }

    currentOrder = order;
    displayOrderInfo(order);
  });

  // 受注情報表示
  function displayOrderInfo(order) {
    container.querySelector("#display-order-number").textContent = order.受注番号 || "-";
    container.querySelector("#display-current-delivery").textContent = order.納期 ? new Date(order.納期).toLocaleString() : "-";
    container.querySelector("#display-order-status").textContent = order.受注ステータス || "-";

    container.querySelector("#order-info-panel").style.display = "block";
  }

  // 判定実行
  container.querySelector("#btn-analyze").addEventListener("click", async () => {
    if (!currentOrder) return;

    const desiredDelivery = container.querySelector("#desired-delivery-input").value;
    if (!desiredDelivery) {
      alert("希望納期を入力してください");
      return;
    }

    await performAnalysis(currentOrder, desiredDelivery);
  });

  // 分析実行
  async function performAnalysis(order, desiredDelivery) {
    // 在庫データ取得
    const stocks = await window.aivicApi.list(1); // 在庫テーブル
    const manufacturingProgress = await window.aivicApi.list(4); // 製造進捗テーブル
    const manufacturingProcesses = await window.aivicApi.list(3); // 製造工程テーブル

    if (!stocks || !manufacturingProgress || !manufacturingProcesses) return;

    // 受注に関連する在庫・進捗データを取得
    const orderStock = stocks.find(s => s.商品ID === order.商品ID) || {};
    const orderProgress = manufacturingProgress.filter(p => p.受注ID === order.受注ID);
    const orderProcesses = manufacturingProcesses.filter(p => p.受注ID === order.受注ID);

    // 在庫状況分析
    const currentStock = orderStock.現在庫数 || 0;
    const requiredStock = 1; // 仮の必要数量
    const shortage = Math.max(0, requiredStock - currentStock);
    const stockStatus = shortage > 0 ? "不足" : "充足";

    // 製造進捗分析
    const avgProgress = orderProgress.length > 0 
      ? Math.round(orderProgress.reduce((sum, p) => sum + (p.進捗率 || 0), 0) / orderProgress.length)
      : 0;

    // 完了予定日計算
    const scheduledCompletion = orderProcesses.length > 0
      ? orderProcesses.reduce((latest, p) => {
          const processDate = new Date(p.予定完了日 || 0);
          return processDate > latest ? processDate : latest;
        }, new Date(0))
      : new Date();

    // 判定ロジック
    const desiredDate = new Date(desiredDelivery);
    const canDeliver = scheduledCompletion <= desiredDate && shortage === 0;
    const delayRisk = scheduledCompletion > desiredDate ? "高" : avgProgress < 50 ? "中" : "低";

    currentAnalysis = {
      order,
      desiredDelivery,
      canDeliver,
      currentStock,
      requiredStock,
      shortage,
      stockStatus,
      avgProgress,
      scheduledCompletion,
      delayRisk,
      orderProgress
    };

    displayAnalysisResult(currentAnalysis);
  }

  // 分析結果表示
  function displayAnalysisResult(analysis) {
    // 判定結果
    const resultEl = container.querySelector("#judgment-result");
    if (analysis.canDeliver) {
      resultEl.textContent = "納期変更可能";
      resultEl.style.background = "rgba(34, 197, 94, 0.2)";
      resultEl.style.color = "#22c55e";
      resultEl.style.border = "1px solid rgba(34, 197, 94, 0.3)";
    } else {
      resultEl.textContent = "納期変更困難";
      resultEl.style.background = "rgba(239, 68, 68, 0.2)";
      resultEl.style.color = "#ef4444";
      resultEl.style.border = "1px solid rgba(239, 68, 68, 0.3)";
    }

    // 在庫状況
    container.querySelector("#current-stock").textContent = analysis.currentStock.toLocaleString();
    container.querySelector("#required-stock").textContent = analysis.requiredStock.toLocaleString();
    container.querySelector("#shortage-stock").textContent = analysis.shortage.toLocaleString();
    container.querySelector("#stock-status").textContent = analysis.stockStatus;

    // 製造完了予定
    container.querySelector("#scheduled-completion").textContent = analysis.scheduledCompletion.toLocaleDateString();
    container.querySelector("#overall-progress").textContent = analysis.avgProgress + "%";
    container.querySelector("#delay-risk").textContent = analysis.delayRisk;

    // 製造進捗テーブル
    const tbody = container.querySelector("#manufacturing-progress-tbody");
    if (analysis.orderProgress.length > 0) {
      tbody.innerHTML = analysis.orderProgress.map(p => `
        <tr>
          <td>${p.工程名 || "-"}</td>
          <td>
            <div style="display: flex; align-items: center; gap: 8px;">
              <div style="flex: 1; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px;">
                <div style="height: 100%; background: var(--primary); border-radius: 3px; width: ${p.進捗率 || 0}%;"></div>
              </div>
              <span style="font-size: 12px; color: var(--text-muted);">${p.進捗率 || 0}%</span>
            </div>
          </td>
          <td>${p.完了予定日時 ? new Date(p.完了予定日時).toLocaleDateString() : "-"}</td>
          <td>${p.実際完了日時 ? new Date(p.実際完了日時).toLocaleDateString() : "-"}</td>
          <td>
            <span style="padding: 2px 8px; border-radius: 12px; font-size: 11px; background: ${getStatusColor(p.進捗状況)};">
              ${p.進捗状況 || "未設定"}
            </span>
          </td>
          <td>${p.遅延フラグ ? "あり" : "なし"}</td>
        </tr>
      `).join("");
    } else {
      tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; color: var(--text-muted); padding: 20px;">製造進捗データがありません</td></tr>';
    }

    container.querySelector("#analysis-result-panel").style.display = "block";
  }

  // ステータス色取得
  function getStatusColor(status) {
    switch (status) {
      case "完了": return "rgba(34, 197, 94, 0.2)";
      case "進行中": return "rgba(59, 130, 246, 0.2)";
      case "遅延": return "rgba(239, 68, 68, 0.2)";
      default: return "rgba(156, 163, 175, 0.2)";
    }
  }

  // 判定結果保存
  container.querySelector("#btn-save-judgment").addEventListener("click", async () => {
    if (!currentAnalysis) return;

    const historyData = {
      受注ID: currentAnalysis.order.受注ID,
      変更前納期: currentAnalysis.order.納期,
      変更後納期: currentAnalysis.desiredDelivery,
      変更理由: "納期変更要求による判定",
      変更申請者ID: "current-user-id", // 実際のユーザーIDを設定
      承認状況: currentAnalysis.canDeliver ? "承認済み" : "要検討",
      作成日時: new Date().toISOString(),
      作成者ID: "current-user-id"
    };

    const saved = await window.aivicApi.save(5, historyData); // 納期変更履歴テーブル
    if (saved) {
      alert("判定結果を保存しました");
    }
  });
}

function(container, apiUrl, tables) {
  // 1. 再描画関数の定義
  function renderDelayedOrders(orders) {
    const tbody = container.querySelector('#delayed-orders-tbody');
    if (!tbody) return;

    tbody.innerHTML = orders.map(order => {
      const deliveryDate = new Date(order.納期);
      const today = new Date();
      const delayDays = Math.max(0, Math.ceil((today - deliveryDate) / (1000 * 60 * 60 * 24)));

      return `
        <tr data-id="${order.受注ID}">
          <td>${order.受注番号 || ''}</td>
          <td>${order.顧客名 || ''}</td>
          <td>${order.商品名 || ''}</td>
          <td>${deliveryDate.toLocaleDateString('ja-JP')}</td>
          <td style="color: #ff6a00; font-weight: 600;">${delayDays}日</td>
          <td>
            <span style="padding: 2px 8px; border-radius: 12px; font-size: 11px; background: rgba(255,106,0,0.1); color: #ff6a00;">
              ${order.受注ステータス || ''}
            </span>
          </td>
          <td>${order.遅延要因 || '材料調達遅延'}</td>
          <td>${order.担当者名 || ''}</td>
        </tr>
      `;
    }).join('');
  }

  // 2. 初期データ読み込みと描画
  async function loadData() {
    try {
      const orders = await window.aivicApi.list(2); // 受注テーブル
      if (orders) {
        // 遅延案件のみフィルタリング
        const delayedOrders = orders.filter(order => {
          const deliveryDate = new Date(order.納期);
          const today = new Date();
          return deliveryDate < today && order.受注ステータス !== '完了';
        });
        renderDelayedOrders(delayedOrders);
        updateKPIs(orders);
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // KPI更新関数
  function updateKPIs(orders) {
    const totalOrders = orders.length;
    const completedOrders = orders.filter(o => o.受注ステータス === '完了').length;
    const delayedOrders = orders.filter(o => {
      const deliveryDate = new Date(o.納期);
      const today = new Date();
      return deliveryDate < today && o.受注ステータス !== '完了';
    }).length;

    const complianceRate = totalOrders > 0 ? ((totalOrders - delayedOrders) / totalOrders * 100).toFixed(1) : 0;

    const complianceEl = container.querySelector('#kpi-compliance-rate');
    const avgDaysEl = container.querySelector('#kpi-avg-days');
    const delayedCountEl = container.querySelector('#kpi-delayed-count');

    if (complianceEl) complianceEl.textContent = `${complianceRate}%`;
    if (delayedCountEl) delayedCountEl.textContent = `${delayedOrders}件`;
  }

  // 3. 分析実行ボタンのイベントリスナー
  const analyzeBtn = container.querySelector('#btn-analyze');
  if (analyzeBtn) {
    analyzeBtn.addEventListener('click', async () => {
      const startDate = container.querySelector('#input-start-date').value;
      const endDate = container.querySelector('#input-end-date').value;
      const category = container.querySelector('#select-category').value;
      const customer = container.querySelector('#select-customer').value;
      const process = container.querySelector('#select-process').value;

      try {
        const orders = await window.aivicApi.list(2);
        if (orders) {
          let filteredOrders = orders;

          // フィルタリング処理
          if (startDate) {
            filteredOrders = filteredOrders.filter(o => new Date(o.受注日) >= new Date(startDate));
          }
          if (endDate) {
            filteredOrders = filteredOrders.filter(o => new Date(o.受注日) <= new Date(endDate));
          }
          if (category) {
            filteredOrders = filteredOrders.filter(o => o.商品カテゴリ === category);
          }
          if (customer) {
            filteredOrders = filteredOrders.filter(o => o.顧客名 === customer);
          }

          const delayedOrders = filteredOrders.filter(order => {
            const deliveryDate = new Date(order.納期);
            const today = new Date();
            return deliveryDate < today && order.受注ステータス !== '完了';
          });

          renderDelayedOrders(delayedOrders);
          updateKPIs(filteredOrders);
        }
      } catch (error) {
        console.error('分析実行エラー:', error);
      }
    });
  }

  // 4. エクスポートボタンのイベントリスナー
  const exportBtn = container.querySelector('#btn-export');
  if (exportBtn) {
    exportBtn.addEventListener('click', async () => {
      try {
        const orders = await window.aivicApi.list(2);
        if (orders) {
          const csvHeader = 'BOM,受注番号,顧客名,商品名,受注日,納期,受注金額,受注ステータス,担当営業,備考\n';
          const csvData = orders.map(order => {
            return [
              '\uFEFF', // BOM
              order.受注番号 || '',
              order.顧客名 || '',
              order.商品名 || '',
              order.受注日 || '',
              order.納期 || '',
              order.受注金額 || '',
              order.受注ステータス || '',
              order.担当営業 || '',
              order.備考 || ''
            ].map(field => `"${String(field).replace(/"/g, '""')}"`).join(',');
          }).join('\n');

          const blob = new Blob([csvHeader + csvData], { type: 'text/csv;charset=utf-8;' });
          const link = document.createElement('a');
          link.href = URL.createObjectURL(blob);
          link.download = `納期実績分析_${new Date().toISOString().split('T')[0]}.csv`;
          link.click();
        }
      } catch (error) {
        console.error('エクスポートエラー:', error);
      }
    });
  }

  // チャート描画関数
  function drawCharts() {
    // 月別納期実績推移チャート
    const monthlyCanvas = container.querySelector('#monthly-trend-chart');
    if (monthlyCanvas) {
      const ctx = monthlyCanvas.getContext('2d');
      const width = monthlyCanvas.width;
      const height = monthlyCanvas.height;

      ctx.clearRect(0, 0, width, height);

      // グリッド線
      ctx.strokeStyle = '#374151';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(40, y);
        ctx.lineTo(width - 20, y);
        ctx.stroke();
      }

      // データライン（納期遵守率）
      const months = ['1月', '2月', '3月', '4月', '5月', '6月'];
      const complianceData = [88, 85, 82, 87, 90, 85];

      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 2;
      ctx.beginPath();

      months.forEach((month, i) => {
        const x = 40 + (width - 60) / (months.length - 1) * i;
        const y = height - (complianceData[i] / 100 * height);

        if (i === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }

        // データポイント
        ctx.fillStyle = '#3b82f6';
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });
      ctx.stroke();

      // ラベル
      ctx.fillStyle = '#9ca3af';
      ctx.font = '11px sans-serif';
      months.forEach((month, i) => {
        const x = 40 + (width - 60) / (months.length - 1) * i;
        ctx.fillText(month, x - 10, height - 5);
      });
    }

    // 工程別所要時間チャート
    const processCanvas = container.querySelector('#process-time-chart');
    if (processCanvas) {
      const ctx = processCanvas.getContext('2d');
      const width = processCanvas.width;
      const height = processCanvas.height;

      ctx.clearRect(0, 0, width, height);

      const processes = ['切断', '加工', '組立', '検査', '梱包'];
      const times = [2.5, 4.2, 3.8, 1.5, 1.2];
      const colors = ['#ff6a00', '#3b82f6', '#00d4aa', '#ffd700', '#8b5cf6'];

      const barWidth = (width - 80) / processes.length;
      const maxTime = Math.max(...times);

      processes.forEach((process, i) => {
        const x = 40 + barWidth * i + barWidth * 0.1;
        const barHeight = (times[i] / maxTime) * (height - 40);
        const y = height - 20 - barHeight;

        ctx.fillStyle = colors[i];
        ctx.fillRect(x, y, barWidth * 0.8, barHeight);

        // ラベル
        ctx.fillStyle = '#9ca3af';
        ctx.font = '11px sans-serif';
        ctx.fillText(process, x, height - 5);
        ctx.fillText(`${times[i]}日`, x, y - 5);
      });
    }

    // 遅延要因分析（円グラフ）
    const delayCanvas = container.querySelector('#delay-factor-chart');
    if (delayCanvas) {
      const ctx = delayCanvas.getContext('2d');
      const width = delayCanvas.width;
      const height = delayCanvas.height;
      const centerX = width / 2;
      const centerY = height / 2;
      const radius = Math.min(width, height) / 2 - 20;

      ctx.clearRect(0, 0, width, height);

      const data = [35, 28, 22, 15];
      const colors = ['#ff6a00', '#3b82f6', '#00d4aa', '#ffd700'];

      let currentAngle = -Math.PI / 2;

      data.forEach((value, i) => {
        const sliceAngle = (value / 100) * Math.PI * 2;

        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
        ctx.closePath();
        ctx.fillStyle = colors[i];
        ctx.fill();

        currentAngle += sliceAngle;
      });
    }
  }

  // 初期化
  loadData();
  drawCharts();

  // 初期データがある場合は即座に描画
  if (tables && tables[2] && tables[2].records) {
    const delayedOrders = tables[2].records.filter(order => {
      const deliveryDate = new Date(order.納期);
      const today = new Date();
      return deliveryDate < today && order.受注ステータス !== '完了';
    });
    renderDelayedOrders(delayedOrders);
    updateKPIs(tables[2].records);
  }
}
